import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
for (const kind of ['mid','post']) {
  const pg=await b.newPage({viewport:{width:390,height:844}})
  await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind='+kind,{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log(kind,'goto',e.message))
  await pg.waitForTimeout(2500)
  const info=await pg.evaluate(()=>{
    const tas=[...document.querySelectorAll('.card > .ref-textarea')]
    return tas.slice(0,4).map(t=>({tag:t.tagName, label:(t.getAttribute('placeholder')||'').slice(0,12), marginTop:getComputedStyle(t).marginTop, marginBottom:getComputedStyle(t).marginBottom, rectTop:Math.round(t.getBoundingClientRect().top), h:Math.round(t.getBoundingClientRect().height)}))
  })
  console.log(kind, JSON.stringify(info))
  // screenshot the 险情补充及影像 card (mid) / first post card
  await pg.evaluate(()=>{ const els=[...document.querySelectorAll('.section-title')]; const t=els.find(e=>/险情补充/.test(e.textContent)); if(t) t.scrollIntoView({block:'center'}) })
  await pg.waitForTimeout(400)
  await pg.screenshot({path:'D:/repository/_ta_'+kind+'.png'})
  await pg.close()
}
await b.close()

